-- ============================================= BIS_GATHER_POLICY ====================================start
DROP TABLE BIS_GATHER_POLICY ;
CREATE TABLE BIS_GATHER_POLICY (
ID VARCHAR2(32) NOT NULL PRIMARY KEY,
GATHER_POLICY_CODE VARCHAR2(4) NOT NULL ,
GATHER_POLICY_NAME VARCHAR2(60)  ,
DEF_DATE DATE NOT NULL ,
LAUNCH_TIME VARCHAR2(6)  ,
GATHER_TYPE VARCHAR2(1)  ,
FRQ_MODE NUMBER  ,
SERIAL_DAY NUMBER  ,
MAX_AMT NUMBER  ,
MIN_AMT NUMBER  ,
GATHER_MODE VARCHAR2(1) NOT NULL ,
GATHER_AMT NUMBER  ,
DOWN_FIXED_AMT NUMBER  ,
APP_NEXT_TIME DATE  ,
DIFFER_SCALE NUMBER  ,
IS_QUICK VARCHAR2(1)  ,
VALID_SIGN VARCHAR2(1)  ,
CREATE_DATE DATE  ,
CREATE_BY VARCHAR2(32)  ,
UPDATE_DATE DATE  ,
UPDATE_BY VARCHAR2(32)  ,
CUR_ID VARCHAR2(32)  ,
AUTO_FILTER_HOLIDAYS VARCHAR2(1)  ,
PURPOSE VARCHAR2(200)  ,
ADD_WORD VARCHAR2(200)  ,
AUTO_FILTER_HOLIDAYS_RULE VARCHAR2(1)  ,
FAIL_HANDLE_METHOD VARCHAR2(10)  );
COMMENT ON TABLE BIS_GATHER_POLICY IS '调拨策略表'
COMMENT ON COLUMN BIS_GATHER_POLICY.CUR_ID IS '币别ID'
COMMENT ON COLUMN BIS_GATHER_POLICY.AUTO_FILTER_HOLIDAYS IS '是否智能跳过节假日 1-是 0-否'
COMMENT ON COLUMN BIS_GATHER_POLICY.PURPOSE IS '用途'
COMMENT ON COLUMN BIS_GATHER_POLICY.ADD_WORD IS '附言'
COMMENT ON COLUMN BIS_GATHER_POLICY.AUTO_FILTER_HOLIDAYS_RULE IS '跳过节假日规则:1,不执行,2,提前执行,3,顺延执行'
COMMENT ON COLUMN BIS_GATHER_POLICY.FAIL_HANDLE_METHOD IS '执行失败处理方式 0,反复执行至成功 1-执行一次'
COMMENT ON COLUMN BIS_GATHER_POLICY.ID IS 'id'
COMMENT ON COLUMN BIS_GATHER_POLICY.GATHER_POLICY_CODE IS '调拨策略代码'
COMMENT ON COLUMN BIS_GATHER_POLICY.GATHER_POLICY_NAME IS '调拨策略名称'
COMMENT ON COLUMN BIS_GATHER_POLICY.DEF_DATE IS '策略生效日期（yyyy/MM/dd）'
COMMENT ON COLUMN BIS_GATHER_POLICY.LAUNCH_TIME IS '策略生效时间'
COMMENT ON COLUMN BIS_GATHER_POLICY.GATHER_TYPE IS '调拨类型0-定时归集，1-实时归集，2-定时下拨'
COMMENT ON COLUMN BIS_GATHER_POLICY.FRQ_MODE IS '调拨周期4-按日，8-按周，16-按月，32-按季，64-按年'
COMMENT ON COLUMN BIS_GATHER_POLICY.SERIAL_DAY IS '调拨日 间隔时长以天为单位周策略：选择周一至周日月策略：选择1号到31号'
COMMENT ON COLUMN BIS_GATHER_POLICY.MAX_AMT IS '金额上限'
COMMENT ON COLUMN BIS_GATHER_POLICY.MIN_AMT IS '金额下限（最小执行额度）'
COMMENT ON COLUMN BIS_GATHER_POLICY.GATHER_MODE IS '策略模式（归集/下拨方式）'
COMMENT ON COLUMN BIS_GATHER_POLICY.GATHER_AMT IS '调拨金额（留底资金金额/取整单位/留底资金金额/固定上划金额/账户固定余额/下拨固定额度）'
COMMENT ON COLUMN BIS_GATHER_POLICY.DOWN_FIXED_AMT IS '下拨固定额度（定时下拨，余额不足时固定额度下拨时，保存下拨固定额度）'
COMMENT ON COLUMN BIS_GATHER_POLICY.APP_NEXT_TIME IS '下一次下拔时间'
COMMENT ON COLUMN BIS_GATHER_POLICY.DIFFER_SCALE IS '比例'
COMMENT ON COLUMN BIS_GATHER_POLICY.IS_QUICK IS '加急标志 1-是 0-否'
COMMENT ON COLUMN BIS_GATHER_POLICY.VALID_SIGN IS '有效标志 1-有效 0-无效'
COMMENT ON COLUMN BIS_GATHER_POLICY.CREATE_DATE IS '创建日期'
COMMENT ON COLUMN BIS_GATHER_POLICY.CREATE_BY IS '创建人登录名称'
COMMENT ON COLUMN BIS_GATHER_POLICY.UPDATE_DATE IS '更新日期'
COMMENT ON COLUMN BIS_GATHER_POLICY.UPDATE_BY IS '更新人登录名称'
-- ============================================= BIS_GATHER_POLICY ======================================end
