COMMENT ON TABLE FEX_PRODUCT IS '外汇产品表'
COMMENT ON COLUMN FEX_PRODUCT.FEX_OPTION1 IS '外汇期权品种1 0-普通期权、1-奇异期权'
COMMENT ON COLUMN FEX_PRODUCT.FEX_OPTION2 IS '外汇期权品种2 1-亚式期权、2-单障碍期权、3-双障碍期权'
COMMENT ON COLUMN FEX_PRODUCT.FEX_OPTION3 IS '外汇期权品种3 1-上涨生效单障碍期权(Up & In)、2-上涨失效单障碍期权(Up & Out)、3-下跌失效单障碍期权(Down & Out)、4-下跌生效单障碍期权(Down & In)、5-单触碰生效双障碍期权(Double In)、6-单触碰失效双障碍期权(Double Out)'
COMMENT ON COLUMN FEX_PRODUCT.FEX_OPTION_TYPE IS '外汇期权类型 0-欧式、1-美式'
COMMENT ON COLUMN FEX_PRODUCT.FEX_OPTION_RATE IS '期权费汇率 0-使用协定汇率、1-使用即期汇率'
