COMMENT ON COLUMN FEX_PRODUCT.IS_SHOW_CLEAR_HOUSE IS '在交易时展示清算所 0-否、1-是'
COMMENT ON COLUMN FEX_PRODUCT.ID IS 'None'
COMMENT ON COLUMN FEX_PRODUCT.PRO_LEVEL IS '层级 0-产品组 1-产品'
COMMENT ON COLUMN FEX_PRODUCT.TRAN_TYPE IS '交易类型 1-外汇交易、2-外汇期权交易、3-调拨交易、4-资金收付交易、5-货币市场交易、6-债券交易'
COMMENT ON COLUMN FEX_PRODUCT.PRO_NAME IS '名称'
