COMMENT ON COLUMN FEX_PRODUCT.TRANGROUP_RULE_ID IS '交易组规则ID'
COMMENT ON COLUMN FEX_PRODUCT.IS_ALLOWED_CHANGE IS '交易组规则是否可以在交易组中更改 1-是 0-否'
COMMENT ON COLUMN FEX_PRODUCT.VALID_SIGN IS '有效标志 1-是 0-否'
COMMENT ON COLUMN FEX_PRODUCT.RMK IS '备注'
COMMENT ON COLUMN FEX_PRODUCT.CREATE_DATE IS 'None'
COMMENT ON COLUMN FEX_PRODUCT.CREATE_BY IS 'None'
COMMENT ON COLUMN FEX_PRODUCT.UPDATE_DATE IS 'None'
COMMENT ON COLUMN FEX_PRODUCT.UPDATE_BY IS 'None'
