-- ============================================= NIS_ALLOCATION_REQ ====================================start
DROP TABLE NIS_ALLOCATION_REQ ;
CREATE TABLE NIS_ALLOCATION_REQ (
ID VARCHAR2(32) NOT NULL PRIMARY KEY,
BILL_NO VARCHAR2(32) NOT NULL ,
TYPE NUMBER NOT NULL ,
CORP_ID VARCHAR2(32) NOT NULL ,
PAYER_ACC_ID VARCHAR2(32)  ,
PAYER_ACC VARCHAR2(50)  ,
PAYER_ACC_NAME VARCHAR2(140)  ,
PAYEE_ACC_ID VARCHAR2(32)  ,
PAYEE_ACC VARCHAR2(50)  ,
PAYEE_ACC_NAME VARCHAR2(140)  ,
MONEY NUMBER NOT NULL ,
WISH_PAYDAY DATE  ,
BURSAR_BILL_NO VARCHAR2(40)  ,
IS_QUICK VARCHAR2(1)  ,
DIF_BANK VARCHAR2(1)  ,
AREA_SIGN VARCHAR2(1)  ,
PURPOSE VARCHAR2(120)  ,
TALLY_DATE DATE  ,
ORDER_NO VARCHAR2(40)  ,
VOUCHER_NO VARCHAR2(40)  ,
CA_INFO_ID VARCHAR2(32)  ,
STATUS NUMBER  ,
ATTACHMENT_ID VARCHAR2(32)  ,
CREATE_DATE DATE  ,
CREATE_BY VARCHAR2(32)  ,
UPDATE_DATE DATE  ,
UPDATE_BY VARCHAR2(32)  ,
BILL_FROM VARCHAR2(2)  ,
ERP_ID VARCHAR2(32)  ,
TALLY_SIGN VARCHAR2(1)  ,
TALLY_CODE VARCHAR2(32)  ,
POOL_SIGN VARCHAR2(1)  ,
TIME_STAMP VARCHAR2(20)  ,
RMK VARCHAR2(200)  ,
PAYEE_COUNTER_ACC VARCHAR2(50)  ,
VOUCHER_STAT VARCHAR2(1)  ,
CUR_ID VARCHAR2(32)  );
COMMENT ON TABLE NIS_ALLOCATION_REQ IS '资金调拨制单表'
COMMENT ON COLUMN NIS_ALLOCATION_REQ.POOL_SIGN IS '资金池标识 0-非资金池;1-资金池'
COMMENT ON COLUMN NIS_ALLOCATION_REQ.TIME_STAMP IS '时间戳'
COMMENT ON COLUMN NIS_ALLOCATION_REQ.RMK IS '备注说明'
COMMENT ON COLUMN NIS_ALLOCATION_REQ.PAYEE_COUNTER_ACC IS '资源值'
COMMENT ON COLUMN NIS_ALLOCATION_REQ.BLEND_SIGN IS '0-未勾兑,1-已勾兑,默认0-未勾兑'
COMMENT ON COLUMN NIS_ALLOCATION_REQ.ID IS 'CMT$流水号ID@'
COMMENT ON COLUMN NIS_ALLOCATION_REQ.BILL_NO IS '单据号码'
COMMENT ON COLUMN NIS_ALLOCATION_REQ.TYPE IS '资金调拨类型 10-上划 11-下拨 12-请款 13-头寸调拨 14-上缴'
COMMENT ON COLUMN NIS_ALLOCATION_REQ.CORP_ID IS '单位ID'
